using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DebuffNextTurnEffect", menuName = "Data/Battle/Effects/Austra/DebuffNextTurn Effect")]
public class DebuffNextTurnEffect : Effect
{
	[SerializeField]
	private Effect debuffNextTurnEffect;

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		ApplyDebuff(amount, effectOwner);
		return 0;
	}

	private void ApplyDebuff(int amount, GameObject effectOwner)
	{
		UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.4f, delegate
		{
			unitEffects.AddEffect(debuffNextTurnEffect, amount);
		});
	}
}
